FROM atom
WHERE molecule_id = 'TR206';

SELECT team_fifa_api_id
FROM Team_Attributes
WHERE buildUpPlaySpeed > 50 AND buildUpPlaySpeed < 60;

SELECT
    CAST(
        COUNT(CASE WHEN fd.language = 'French' AND (c.power IS NULL OR c.power = '*') THEN 1 END) AS REAL
    ) /
    CAST(
        COUNT(CASE WHEN c.power IS NULL OR c.power = '*' THEN 1 END) AS REAL
    ) * 100 AS percentage
FROM cards c
JOIN foreign_data fd ON fd.uuid = c.uuid;

SELECT CAST(
    COUNT(*) AS REAL
) / COUNT(p.id) * 100 AS percentage
FROM Player p
JOIN Player_Attributes pa ON pa.player_api_id = p.player_api_id
WHERE p.height < 180 AND pa.overall_rating > 70;

SELECT CAST(SUM(CASE WHEN gender_id = 2 THEN 1 ELSE 0 END) AS REAL) /
       CAST(SUM(CASE WHEN gender_id = 1 THEN 1 ELSE 0 END) AS REAL) AS ratio
FROM superhero;

SELECT EILName
FROM schools
