SELECT CAST(
    COUNT(DISTINCT CASE WHEN Consumption > 528.3 THEN CustomerID END) AS REAL
) / COUNT(DISTINCT CustomerID) AS percentage
FROM yearmonth
WHERE Date = '201202';

SELECT CAST(
    COUNT(CASE WHEN c.country = 'Germany' AND r.name = 'European Grand Prix' THEN 1 END) AS REAL
) / COUNT(*) * 100 AS percentage
FROM races r
JOIN circuits c ON r.circuitId = c.circuitId
WHERE r.name = 'European Grand Prix';

